if (!window.Tech) {
  window.Tech = {}
}
if (!window.Tech.$dev) {
  window.Tech.$dev = {}
}

/**
 * 根据菜单ID查找对应的菜单项
 * @param {Array} menus - 菜单数组
 * @param {string} menuId - 菜单项ID
 * @returns {Object|null} 找到的菜单项或null
 */
function findMenuById(menus, menuId) {
  return menus.find((menu) => menu.id === menuId) || null
}

/**
 * 递归构建菜单路径
 * @param {Array} menus - 菜单数组
 * @param {string} menuId - 当前菜单项ID
 * @returns {string} 构建的路径
 */
function buildMenuPath(menus, menuId) {
  const menu = findMenuById(menus, menuId)
  if (!menu) return ''

  // 如果有父级菜单，递归获取父级路径
  if (menu.parent_ids) {
    // 只有存在parent_ids的才需要递归查找父级
    const parentPath = buildMenuPath(menus, menu.parent_ids)
    return parentPath ? `${parentPath}/${menu.name}` : `/${menu.name}`
  }

  return `/${menu.name}`
}

/**
 * 处理菜单数组，为每个菜单项添加path字段
 * @param {Array} menusData - 原始菜单数组
 * @returns {Array} 处理后的菜单数组
 */
function processMenusWithPath(menusData) {
  return menusData.map((menu) => {
    // 根节点没有parent_ids
    if (!menu.parent_ids) {
      return { ...menu, path: `/${menu.name}` }
    }

    // 为当前菜单项构建完整路径
    const path = buildMenuPath(menusData, menu.id)
    return { ...menu, path }
  })
}

/**
 * 筛选出叶子节点菜单
 * @param {Array} menusWithPath - 带路径的菜单数组
 * @returns {Array} 叶子节点菜单数组
 */
function filterLeafMenuItems(menusWithPath) {
  // 收集所有作为父级的菜单ID
  const parentMenuIds = new Set()
  menusWithPath.forEach((menu) => {
    if (menu.parent_ids) {
      parentMenuIds.add(menu.parent_ids)
    }
  })

  // 筛选出不是父级的菜单（即叶子节点）
  return menusWithPath.filter((menu) => !parentMenuIds.has(menu.id))
}

window.Tech.$dev.genAppEffect = async (appCompName, appModuleName) => {
  // 菜单数据
  const menusData = tech_app.page.getNode('menu_meta_siderbar')?.$ds?.appsMenus || []

  // 收集所有的扩展视图ID和对应的扩展名，包括处理pre前缀的情况
  const collectExtendViewIdsWithNames = async () => {
    const result = []

    // 遍历tech_app.extendView，保留key（扩展名）和value
    let getParams = window?.tech_apps_comps?.[appCompName]?.getParams || 
    window?.['main-' + appCompName + '.umd.min']?.getParams ||
    window?.['main-' + appModuleName + '.umd.min']?.getParams || null

    let extendObj = {}
    if (getParams) {
      if (getParams.constructor.name === 'AsyncFunction') {
        // console.log('11111')
        let r = await getParams()
        // console.log('33333', r)
        extendObj = r?.extendView || {}
      } else {
        extendObj = getParams?.()?.extendView || {}
      }
    }
    console.log('里面的扩展', extendObj)
    for (let k in extendObj) {
      let extName = k
      let view = extendObj[k]

      if (view.selector && view.selector.attr === 'id') {
        const { value, pre } = view.selector
        // 如果有pre前缀数组，拼接每个前缀
        if (pre && Array.isArray(pre)) {
          pre.forEach((prefix) => {
            result.push({ id: `${prefix}${value}`, extName })
          })
        } else {
          // 没有pre前缀时，返回原始value
          result.push({ id: value, extName })
        }
      }
    }

    return result.filter((item) => item.id !== null)
  }

  // 获取带扩展名的ID列表
  const extendViewIdsWithNames = await collectExtendViewIdsWithNames()

  // 处理菜单数据
  const menusWithPath = processMenusWithPath(menusData)
  const leafMenuItems = filterLeafMenuItems(menusWithPath)

  // 为每个ID找到最长匹配的叶子节点
  const findLongestLeafMatch = (id) => {
    const matchingLeaves = leafMenuItems.filter((leaf) => id?.startsWith?.(leaf.name))
    if (matchingLeaves.length === 0) return null

    return matchingLeaves.reduce((longest, current) =>
      current.name.length > longest.name.length ? current : longest
    )
  }

  // 构建ID与叶子节点匹配关系，并记录未匹配的ID
  const unmatchedIds = []
  const leafPrefixMatches = {}

  // 使用带扩展名的ID列表进行处理
  extendViewIdsWithNames.forEach(({ id, extName }) => {
    const longestMatch = findLongestLeafMatch(id)

    if (longestMatch) {
      // 有匹配项时记录匹配关系
      leafPrefixMatches[id] = {
        matchedLeafName: longestMatch.name,
        matchedLeafId: longestMatch.id,
        path: longestMatch.path,
        extName: extName // 记录对应的扩展名
      }
    } else {
      // 未匹配到叶子节点时记录ID和扩展名
      unmatchedIds.push({
        extendId: id,
        extendName: extName
      })
    }
  })

  // 输出日志
  if (unmatchedIds.length) {
    console.log(
      '%c未匹配到菜单的扩展，请拷贝扩展名在工程查找，确认相关业务扩展是否已包含在按需加载正则页面里面:',
      'color: red; font-weight: bold;',
      unmatchedIds
    )
  }

  // 提取并处理路径
  const extractTwoLevelPaths = () => {
    return Object.values(leafPrefixMatches)
      .map((match) => {
        if (!match?.path) return ''

        const pathParts = match.path.split('/').filter(Boolean)
        // 只保留两级路径
        return pathParts.length >= 2 ? `/${pathParts[0]}/${pathParts[1]}` : ''
      })
      .filter(Boolean) // 过滤空字符串
  }

  // 获取唯一的两级路径
  const uniqueTwoLevelPaths = [...new Set(extractTwoLevelPaths())]

  // 转义正则表达式特殊字符
  const escapeRegExp = (string) => {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  }

  // 生成正则表达式模式
  const generateRegexPattern = () => {
    if (uniqueTwoLevelPaths.length === 0) return ''

    // 单个路径不需要括号包裹
    if (uniqueTwoLevelPaths.length === 1) {
      const path = uniqueTwoLevelPaths[0]
      return `^/${escapeRegExp(path.slice(1))}/?`
    }

    // 多个路径使用括号分组
    const pathGroups = uniqueTwoLevelPaths
      .map((path) => `(${escapeRegExp(path.slice(1))}/?)`)
      .join('|')

    return `^/${pathGroups}`
  }

  return {
    regexPattern: generateRegexPattern(), // 按需加载配置字符串
    unmatched: unmatchedIds, // 未匹配到菜单的扩展ID数组
    extendViewIdsWithNames // 带扩展名的ID列表
  }
}

// 开发态运行获取默认生成的按需加载配置
window.Tech.$dev.getEffect = () => {
  if (!Tech.token.get()) {
    console.log(' 请先登录进去再运行 ')
    return
  }
  let failApps = {}
  let consultObj = {}
  let apps = window.tech.srcOutApps.appsDetail
  for (let appName in apps) {
    let frontAppName = ''
    for (let compName in apps[appName]?.[window?.tech?.env || 'master']) {
      if (compName.startsWith('tech-')) {
        frontAppName = compName.replace('tech-', '')
      } else {
        frontAppName = compName
      }
      let useAppName = frontAppName // appName
      let detail = apps[appName]?.[window?.tech?.env || 'master']?.[compName]?.view_file_json
      if (detail && !detail?.effectPaths && !detail?.effectPageIds) {
        console.log(' === useAppName == ', useAppName)
        let effect =
          window.Tech.$dev.genAppEffect(appName) || window.Tech.$dev.genAppEffect(frontAppName)
        if (effect) {
          console.log(`请在app：' + ${useAppName} + '/config/app.json 里面加按需加载配置: 
"effectPaths":  {
  "includeRegExp": "${effect}"
}
          `)
          consultObj[useAppName] = { includeRegExp: effect }
        } else {
          failApps[useAppName] = { includeRegExp: '' }
          console.log(' === app ' + useAppName + ' 匹配按需加载配置失败~~~')
        }
      }
    }
  }
  console.log(
    '或者在工程的config/apps.json 加按需加载配置:' +
      ' \n"appsEffectPaths": ' +
      JSON.stringify(consultObj, null, 2)
  )
  if (Object.keys(failApps).length) {
    console.log('匹配失败的app列表  \n"appsEffectPaths": ' + JSON.stringify(failApps, null, 2))
  }
}
